  function dashboardStatus(entry){if(entry.result.status==='skipped')return 'skipped';if(entry.result.done||entry.result.status==='completed')return 'completed';if(entry.result.status==='todo')return 'todo';return entry.result.status==='progress'||resultHasDetails(entry.result)?'progress':'todo'}
