  function taskCardColor(task){const match=/^#([\da-f]{6})$/i.exec(task?.color||'');if(!match)return '';const value=parseInt(match[1],16),r=value>>16,g=(value>>8)&255,b=value&255;return `rgba(${r},${g},${b},.2)`}
  function scheduleCardColor(task,date){const chosen=taskCardColor(task);if(chosen)return chosen;const index=tasks.filter(item=>occursOn(item,date)).sort((a,b)=>a.start.localeCompare(b.start)).findIndex(item=>item.id===task.id);return ['#fff2d9','#dfedff','#ffe5e7','#ddf7e8'][(index<0?0:index)%4]}
