  function buildProductivityTrend(records,start,end){
    const first=new Date(`${start}T12:00:00`),last=new Date(`${end}T12:00:00`),span=Math.max(1,Math.round((last-first)/86400000)+1),step=1,buckets=[];
    for(let offset=0;offset<span;offset+=step){const date=new Date(first);date.setDate(date.getDate()+offset);const stop=new Date(date);stop.setDate(stop.getDate()+step);buckets.push({key:dateString(date),label:date.toLocaleDateString('en-US',{month:'short',day:'numeric'}),growthPoints:0,activities:new Map(),stop:dateString(stop)})}
    for(const record of records){const bucket=buckets.find(item=>record.result.date>=item.key&&record.result.date<item.stop);if(!bucket)continue;bucket.growthPoints+=record.growthPoints;const previous=bucket.activities.get(record.task.id);bucket.activities.set(record.task.id,{task:record.task,growthPoints:(previous?.growthPoints||0)+record.growthPoints,color:productivityActivityColor(record.task)})}
    return buckets.map(({stop,activities,...bucket})=>({...bucket,segments:[...activities.values()].filter(item=>item.growthPoints>0).sort((a,b)=>a.task.title.localeCompare(b.task.title))}))
