  $: nextTask=currentWidgetTask||day.entries.find(e=>{const [hour,minute]=e.task.start.split(':').map(Number);return !e.result.done&&e.result.status!=='skipped'&&hour*60+minute>nowMinutes});
  $: dashboardColumns=[{name:'To Do',tone:'todo',icon:'○',entries:day.entries.filter(e=>dashboardStatus(e)==='todo')},{name:'In Progress',tone:'progress',icon:'◷',entries:day.entries.filter(e=>dashboardStatus(e)==='progress')},{name:'Completed',tone:'completed',icon:'✓',entries:day.entries.filter(e=>dashboardStatus(e)==='completed')},{name:'Skipped',tone:'skipped',icon:'↷',entries:day.entries.filter(e=>dashboardStatus(e)==='skipped')}];
