  function occursOn(task,date){if(date<task.date)return false;const dow=new Date(`${date}T12:00:00`).getDay(),start=new Date(`${task.date}T12:00:00`).getDay();return task.repeat==='daily'||task.repeat==='weekdays'&&dow!==0&&dow!==6||task.repeat==='weekly'&&dow===start||task.repeat==='custom'&&task.weekdays?.includes(dow)||(!task.repeat||task.repeat==='none')&&date===task.date}
  function makeCalendarCells(month){const first=new Date(month.getFullYear(),month.getMonth(),1),offset=(first.getDay()+6)%7;return Array.from({length:42},(_,i)=>{const date=new Date(month.getFullYear(),month.getMonth(),i-offset+1);const key=dateString(date);return {key,day:date.getDate(),current:date.getMonth()===month.getMonth(),today:key===today(),entries:tasks.filter(t=>occursOn(t,key))}})}
  function makeDateCells(month){const first=new Date(month.getFullYear(),month.getMonth(),1),offset=(first.getDay()+6)%7;return Array.from({length:42},(_,i)=>{const date=new Date(month.getFullYear(),month.getMonth(),i-offset+1);return {key:dateString(date),day:date.getDate(),current:date.getMonth()===month.getMonth()}})}
  function navigate(name){view=name;filter='All';collection='All';if(name==='Projects')selectedProjectId='';if(name==='Today')selectedDate=today();if(name==='Calendar')calendarMonth=new Date(`${selectedDate}T12:00:00`);load()}
