  function parsedProjectEvaluation(project){try{return project?.evaluationData?JSON.parse(project.evaluationData):null}catch{return null}}
  async function evaluateProjectOverview(){if(!selectedProject)return;projectEvaluationError='';if(!projectObjectives.length){projectEvaluationError='Add a project objective first.';return}if(!completedProjectTasks){projectEvaluationError='Complete and save a project task result first.';return}if(!defaultAIConnected()){projectEvaluationError='Connect an AI provider in Settings first.';return}projectEvaluating=true;try{const raw=await api.EvaluateProjectOverview(selectedProject.id);const parsed=JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/g,''));if(!Array.isArray(parsed.tasks)||!parsed.tasks.length)throw Error('No task scores returned. Please try again.');parsed.tasks=parsed.tasks.map(item=>({...item,score:Math.max(0,Math.min(100,Math.round(Number(item.score)||0))),reason:String(item.reason||'')}));parsed.suggestions=Array.isArray(parsed.suggestions)?parsed.suggestions.map(String):[];const xp=parsed.tasks.reduce((sum,item)=>sum+item.score,0);const level=Math.floor(xp/500)+1;const project={...selectedProject,level,xp,evaluationData:JSON.stringify(parsed),evaluatedAt:new Date().toISOString()};await api.SaveProject(project);await load();projectOverviewTab='ai'}catch(e){projectEvaluationError=String(e)}finally{projectEvaluating=false}}
