  function setEditorFontSize(event,target='notes'){const editor=getEditor(target);if(!editor)return;const size=event.currentTarget.value;if(size)editor.chain().focus().setFontSize(`${size}px`).run();else editor.chain().focus().unsetFontSize().run();if(target==='notes')syncEditorToolbar()}
