  async function insertImageFiles(editor,files,pos=null){const images=[];for(const file of files){if(!file.type.startsWith('image/')){error='Please choose an image file.';continue}if(file.size>5*1024*1024){error='Images must be 5 MB or smaller.';continue}const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)});images.push({type:'image',attrs:{src,alt:file.name,title:file.name}})}if(!images.length)return;if(pos!==null)editor.commands.insertContentAt(pos,images);else editor.chain().focus().insertContent(images).run()}
  function addResultPoint(list){if(list==='activity')activityItems=[...activityItems,''];else outputItems=[...outputItems,'']}
  function removeResultPoint(list,index){if(list==='activity')activityItems=activityItems.filter((_,i)=>i!==index);else outputItems=outputItems.filter((_,i)=>i!==index);if(list==='activity'&&!activityItems.length)activityItems=[''];if(list==='output'&&!outputItems.length)outputItems=['']}
  function resultPoints(value){const values=(value||'').split('\n').map(item=>item.trim()).filter(Boolean);return values.length?values:['']}
  async function createSummaryEditor(){if(!summaryEditorElement)return;const [coreModule,starterModule,imageModule,fileModule,textStyleModule]=await Promise.all([import('@tiptap/core'),import('@tiptap/starter-kit'),import('@tiptap/extension-image'),import('@tiptap/extension-file-handler'),import('@tiptap/extension-text-style')]);if(!resultDialog||!summaryEditorElement)return;const {Editor}=coreModule,StarterKit=starterModule.default,Image=imageModule.default,FileHandler=fileModule.default,{TextStyleKit}=textStyleModule;summaryTiptap?.destroy();summaryTiptap=new Editor({element:summaryEditorElement,extensions:[StarterKit,TextStyleKit,Image.configure({allowBase64:true,HTMLAttributes:{class:'note-image'}}),FileHandler.configure({allowedMimeTypes:['image/png','image/jpeg','image/gif','image/webp'],consumePasteEvent:true,onPaste:(editor,files)=>insertImageFiles(editor,files),onDrop:(editor,files,pos)=>insertImageFiles(editor,files,pos)})],content:result.summary||'',onUpdate:({editor})=>{result.summary=editor.getHTML()}});summaryEditorReady=true}
  function destroySummaryEditor(){summaryTiptap?.destroy();summaryTiptap=null}
  function loadSummaryImage(event){const files=Array.from(event.currentTarget.files||[]);event.currentTarget.value='';if(summaryTiptap)insertImageFiles(summaryTiptap,files)}
  function closeTaskDialog(){destroyNotesEditor();taskDialog=false}
  async function editResult(entry){destroySummaryEditor();summaryEditorReady=false;activeTask=entry.task;result={...newResult(entry.task.id,selectedDate),...entry.result};activityItems=resultPoints(result.activity);outputItems=resultPoints(result.output);resultDialog=true;error='';await tick();await createSummaryEditor()}
  function openResultEntry(entry){if(entry.result.done){activityOverviewEntry=entry;aiEvaluation=cleanAIEvaluation(entry.result.aiEvaluation||'');aiScore=Number.isInteger(entry.result.aiScore)?entry.result.aiScore:null}else editResult(entry)}
  function closeActivityOverview(){activityOverviewEntry=null;aiEvaluation='';aiScore=null}
  function aiProviderConnected(provider=aiProviderDraft){return Boolean(aiSettings.providers?.[provider]?.connected)}
  function defaultAIConnected(){return aiProviderConnected(aiSettings.defaultProvider)}
  async function chooseAIProvider(event){const provider=event.currentTarget.value;aiProviderDraft=provider;aiKeyInput='';aiModelInput=aiSettings.providers?.[provider]?.model||'';if(!aiProviderConnected(provider))return;aiBusy=true;try{aiSettings=await api.SetAIDefaultProvider(provider);aiModelInput=aiSettings.providers?.[provider]?.model||aiModelInput;showFeedback(true,`${aiProviders.find(item=>item.id===provider)?.name||provider} is now the default AI provider.`)}catch(e){showFeedback(false,String(e))}finally{aiBusy=false}}
  async function connectAI(){if(!aiKeyInput.trim()){showFeedback(false,`Enter your ${aiProviders.find(item=>item.id===aiProviderDraft)?.name||'AI'} API key first.`);return}aiBusy=true;try{aiSettings=await api.ConnectAI(aiProviderDraft,aiKeyInput.trim());aiKeyInput='';aiModelInput=aiSettings.providers?.[aiProviderDraft]?.model||aiModelInput;showFeedback(true,`${aiProviders.find(item=>item.id===aiProviderDraft)?.name||'AI'} is connected and set as the default provider.`)}catch(e){showFeedback(false,String(e))}finally{aiBusy=false}}
  async function saveAIProviderModel(){aiBusy=true;try{aiSettings=await api.SetAIProviderModel(aiProviderDraft,aiModelInput.trim());aiModelInput=aiSettings.providers?.[aiProviderDraft]?.model||aiModelInput;showFeedback(true,`Model ${aiModelInput} is saved for ${aiProviders.find(item=>item.id===aiProviderDraft)?.name||aiProviderDraft}.`)}catch(e){showFeedback(false,String(e))}finally{aiBusy=false}}
  async function disconnectAI(){const provider=aiProviderDraft;aiBusy=true;try{aiSettings=await api.DisconnectAI(provider);if(!aiSettings.providers?.[provider]?.connected&&aiSettings.defaultProvider)aiProviderDraft=aiSettings.defaultProvider;showFeedback(true,`${aiProviders.find(item=>item.id===provider)?.name||'AI provider'} was disconnected and its saved key was removed.`)}catch(e){showFeedback(false,String(e))}finally{aiBusy=false}}
  function toggleAISettings(){if(defaultAIConnected()){aiProviderDraft=aiSettings.defaultProvider;disconnectAI();return}aiSettingsExpanded=true}
  async function evaluateActivity(){
    if(!activityOverviewEntry)return;
    if(!defaultAIConnected()){showFeedback(false,'Connect an AI provider and choose it as default in Settings first.');return}
    aiEvaluating=true;aiEvaluation='';aiScore=null;
    try{
      const {task,result}=activityOverviewEntry;
      const response=await api.EvaluateActivity(task.id,result.date);
      const scoreMatch=response.match(/^\s*SCORE\s*:\s*(100|[1-9]?\d)\s*\/\s*100\s*$/im);
      const growthMatch=response.match(/^\s*GROWTH_POINTS\s*:\s*(100|\d{1,2})\s*$/im);
      if(!scoreMatch||!growthMatch)throw Error('The AI response did not include a valid achievement score and Growth Points value. Please try again.');
      const score=Number(scoreMatch[1]),aiGrowthPoints=Number(growthMatch[1]);
      const evaluation=cleanAIEvaluation(response.replace(scoreMatch[0],'').replace(growthMatch[0],'').trim());
      await api.SaveAIEvaluation(task.id,result.date,score,aiGrowthPoints,evaluation);
      aiScore=score;aiEvaluation=evaluation;
      const updatedResult={...result,aiScore:score,aiGrowthPoints,aiEvaluation:evaluation};
      activityOverviewEntry={...activityOverviewEntry,result:updatedResult};
      allResults=allResults.map(item=>item.taskId===task.id&&item.date===result.date?updatedResult:item);
    }catch(e){showFeedback(false,String(e))}finally{aiEvaluating=false}
  }
  function closeResultDialog(){destroySummaryEditor();summaryEditorReady=false;resultDialog=false}
  function requestConfirmation(title,message,confirmLabel,action,danger=false){confirmDialog={title,message,confirmLabel,action,danger}}
  function showFeedback(success,message){feedbackDialog={success,title:success?'Success':'Something went wrong',message}}
  async function runConfirmedAction(){const action=confirmDialog?.action;confirmDialog=null;if(action)await action()}
  function saveTask(){if(!editing.title.trim()){showFeedback(false,'Please enter a task title.');return}if(editing.repeat==='custom'&&!editing.weekdays.length){showFeedback(false,'Select at least one day for this repeating task.');return}requestConfirmation(editing.id?'Save changes?':'Save this task?',`Save “${editing.title.trim()}” to your schedule?`,'Save Task',performSaveTask)}
  async function performSaveTask(){try{editing.notes=tiptapEditor?.getHTML()||'';await api.SaveTask({...editing,duration:Number(editing.duration)});closeTaskDialog();await load();showFeedback(true,`“${editing.title.trim()}” was saved.`)}catch(e){showFeedback(false,String(e))}}
  function saveResult(){if(result.done&&!activityItems.some(item=>item.trim())){error='Record at least one activity under “What did you do?” before completing this task.';return}requestConfirmation('Save activity result?',`Save the activity result for “${activeTask?.title||'this task'}”?`,'Save Result',performSaveResult)}
  async function performSaveResult(){try{result.activity=activityItems.map(item=>item.trim()).filter(Boolean).join('\n');result.output=outputItems.map(item=>item.trim()).filter(Boolean).join('\n');result.summary=summaryTiptap?.getHTML()||result.summary;if(result.done&&!result.activity){error='Record at least one activity under “What did you do?” before completing this task.';return}if(result.done)result.status='completed';else if(result.status==='completed')result.status=resultHasDetails(result)?'progress':'todo';await api.SaveResult({...result,actualMinutes:Number(result.actualMinutes)});closeResultDialog();await load();showFeedback(true,`Activity result for “${activeTask?.title||'this task'}” was saved.`)}catch(e){showFeedback(false,String(e))}}
  function setProductivityRange(value){productivityRange=value;if(value==='custom'){productivityStart=periodBounds(30).start;productivityEnd=today()}}
  async function toggleDone(entry){if(!entry.result.done){await editResult(entry);result.done=true;return}try{await api.SaveResult({...newResult(entry.task.id,selectedDate),...entry.result,done:false,status:'todo'});await load()}catch(e){error=String(e)}}
  async function skipWidgetTask(entry,event){event.stopPropagation();try{await api.SaveResult({...newResult(entry.task.id,selectedDate),...entry.result,done:false,status:'skipped'});await load()}catch(e){error=String(e)}}
  function startDashboardDrag(event,entry){draggedTaskId=entry.task.id;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',entry.task.id)}
  function endDashboardDrag(){draggedTaskId='';dragOverStatus=''}
  async function dropDashboardTask(event,targetStatus){event.preventDefault();dragOverStatus='';const id=event.dataTransfer.getData('text/plain')||draggedTaskId;const entry=day.entries.find(item=>item.task.id===id);draggedTaskId='';if(!entry||dashboardStatus(entry)===targetStatus)return;if(targetStatus==='completed'&&!entry.result.activity?.trim()){await editResult(entry);result.done=true;return}try{await api.SaveResult({...newResult(entry.task.id,selectedDate),...entry.result,status:targetStatus,done:targetStatus==='completed'});await load()}catch(e){error=String(e)}}
  function deleteTask(task){requestConfirmation('Delete this task?',`“${task.title}” and its saved results will be deleted.`,'Delete Task',()=>performDeleteTask(task),true)}
  async function performDeleteTask(task){try{await api.DeleteTask(task.id);await load();showFeedback(true,`“${task.title}” was deleted.`)}catch(e){showFeedback(false,String(e))}}
  function deleteActivityResult(entry){requestConfirmation('Delete this activity log?',`Delete the saved result for “${entry.task.title}” on ${entry.result.date}? The task itself will remain on your schedule.`,'Delete Result',()=>performDeleteActivityResult(entry),true)}
  async function performDeleteActivityResult(entry){try{await api.DeleteResult(entry.task.id,entry.result.date);await load();showFeedback(true,'Activity log entry deleted.')}catch(e){showFeedback(false,String(e))}}
  async function enterMini(){try{await api.ToggleOverview()}catch(e){error=String(e)}}
  async function toggleTrayIcon(){const next=!trayIconEnabled;traySettingsBusy=true;try{await api.SetTrayIconEnabled(next);trayIconEnabled=next;error=''}catch(e){error=String(e)}finally{traySettingsBusy=false}}
  async function toggleAutoStart(){const next=!autoStartEnabled;autoStartBusy=true;try{await api.SetAutoStartEnabled(next);autoStartEnabled=next;error=''}catch(e){error=String(e)}finally{autoStartBusy=false}}
  async function saveUserName(){const name=nameDraft.trim();if(!name)return;nameSaving=true;try{await api.SetUserName(name);userName=name;nameDraft=name;showNamePrompt=false;error=''}catch(e){error=String(e)}finally{nameSaving=false}}
  async function restore(){try{await api.RestoreFull()}catch(e){error=String(e)}}
  async function exit(){try{await api.ExitApp()}catch(e){error=String(e)}}
  function toggleWeekday(n){editing.weekdays=editing.weekdays.includes(n)?editing.weekdays.filter(x=>x!==n):[...editing.weekdays,n]}
</script>

{#if mini}
  <div class="h-screen bg-white p-2 overflow-hidden cursor-move rounded-2xl select-none" style="--wails-draggable: drag" role="button" tabindex="0" on:click={restore} on:keydown={(e)=>e.key==='Enter'&&restore()}>
    <div class="flex items-center justify-between"><div class="flex items-center gap-2 text-[14px] font-extrabold"><span class="w-6 h-6 bg-[#5473E6] text-white grid place-items-center rounded-md"><Check size={14}/></span>DailyFlow</div><div class="flex gap-1" style="--wails-draggable: no-drag"><button class="p-1.5 bg-slate-100 rounded-md" title="Open planner" on:click={(e)=>{e.stopPropagation();restore()}}><ExternalLink size={13}/></button><button class="p-1.5 bg-rose-50 text-rose-600 rounded-md" title="Exit" on:click={(e)=>{e.stopPropagation();exit()}}><Power size={13}/></button></div></div>
    <div class="rounded-md bg-sky-50 p-2 mt-2 mini-next-activity">
      <div class="min-w-0 flex-1">
        <div class="text-[10px] font-bold text-sky-600 tracking-wider">{currentWidgetTask?'NOW':'UP NEXT'}</div>
        {#if nextTask}
          <div class="text-[12px] font-bold mt-0.5 truncate">{nextTask.task.title}</div>
          <p class="text-[10px] text-slate-500">{nextTask.task.start} · {nextTask.task.duration} minutes</p>
          <div class="flex gap-1 mt-1" style="--wails-draggable: no-drag">
            <button class="w-7 h-7 inline-grid place-items-center rounded-md bg-emerald-600 text-white hover:bg-emerald-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-emerald-700" aria-label="Complete this activity" title="Complete this activity" on:click={(event)=>{event.stopPropagation();api.OpenActivityResult(nextTask.task.id,selectedDate).catch(e=>error=String(e))}}><Check size={14}/></button>
            <button class="w-7 h-7 inline-grid place-items-center rounded-md bg-white text-slate-600 hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-slate-500" aria-label="Skip this activity" title="Skip this activity" on:click={(event)=>skipWidgetTask(nextTask,event)}><SkipForward size={14}/></button>
          </div>
        {:else}
          <div class="text-[12px] font-semibold mt-1">No upcoming activities</div>
          <p class="text-[10px] text-slate-500">No more activities today</p>
        {/if}
      </div>
      <img class="feature-icon feature-icon-focus" src={focusTimerIcon} alt="" aria-hidden="true"/>
    </div>
  </div>
{:else}
  <div class="flex min-h-screen bg-[#f4f6fa] text-[#273344]">
    <aside class="w-[222px] shrink-0 bg-[#f8f9fc] border-r border-[#e9ebf2] px-6 py-7 flex flex-col min-h-screen">
      <div class="flex items-center gap-2.5 mb-9"><span class="w-8 h-8 rounded-md bg-[#5473E6] text-white grid place-items-center"><Check size={18} strokeWidth={3}/></span><span class="font-extrabold tracking-tight text-lg">DailyFlow<span class="text-[#5473E6]">.</span></span></div>
      <div class="space-y-1">
        {#each [{name:'Dashboard',icon:LayoutDashboard},{name:'Projects',icon:FolderKanban},{name:'Productivity Matrix',icon:Trophy},{name:'Today',icon:ListTodo},{name:'Upcoming',icon:CalendarClock},{name:'Calendar',icon:CalendarDays},{name:'All activities',icon:Archive},{name:'Settings',icon:SettingsIcon}] as item}
          <button class:active={view===item.name} class="side-link w-full flex items-center gap-3 py-2.5 px-3 text-[12px] font-semibold" on:click={()=>navigate(item.name)}><svelte:component this={item.icon} size={15} strokeWidth={1.8}/>{item.name}</button>
        {/each}
      </div>
      <div class="h-px bg-[#e9ecf2] my-7"></div><div class="flex items-center justify-between text-[12px] text-slate-400 uppercase tracking-[1.4px] font-bold px-3 mb-3"><span>Collections</span><Plus size={13}/></div>
      <div class="space-y-1">
        {#each categories as c}<button class="w-full flex items-center gap-3 py-2.5 px-3 text-[13px] text-slate-600 hover:bg-white rounded-md" on:click={()=>{view='Today';filter='All';collection=c;load()}}><span class="w-2 h-2 rounded-sm" style:background={palette[c].text}></span>{c}</button>{/each}
      </div>
      <div class="mt-auto pt-7"><button class="w-11 h-11 bg-[#5473E6] rounded-md text-white grid place-items-center" title="Add task" on:click={()=>editTask()}><Plus size={20}/></button><div class="text-[12px] mt-4 text-slate-400">{isPreview?'Browser preview · local data':'Offline · portable data'}</div><button class="mt-3 text-[13px] text-rose-500 flex gap-2 items-center" on:click={exit}><Power size={13}/> Exit DailyFlow</button></div>
    </aside>
    <main class="flex-1 min-w-0 bg-white px-9 xl:px-12 py-9">
      <div class="flex items-start justify-between gap-4 mb-9"><div><p class="text-[12px] font-bold uppercase tracking-[2px] text-[#5473E6] mb-2">YOUR DAILY SPACE</p><h1 class="text-[25px] font-extrabold tracking-tight">{view==='Projects'&&selectedProject?selectedProject.name:view==='Dashboard'?'Dashboard':view==='Today'?'Today Task':view==='All activities'?'Activity log':view}</h1><p class="text-xs text-slate-400 mt-2">{view==='All activities'?'A timeline of your task activity and results':view==='Productivity Matrix'?'Effort, consistency, reported outputs, and measurable change':view==='Dashboard'?`${dashboardGreeting} · Your day at a glance`:`${greeting} · Make every day count`}</p></div><div class="flex items-center gap-2">{#if view!=='Calendar'&&view!=='All activities'&&view!=='Settings'&&view!=='Productivity Matrix'&&view!=='Projects'}<input class="text-[13px] border border-slate-200 rounded-md py-2 px-2" type="date" bind:value={selectedDate} on:change={load}/>{/if}{#if view==='Dashboard'}<div class="dashboard-view-toggle" aria-label="Dashboard layout"><button class:dashboard-view-selected={dashboardMode==='cards'} aria-label="Card view" aria-pressed={dashboardMode==='cards'} title="Card view" on:click={()=>dashboardMode='cards'}><LayoutGrid size={16}/></button><button class:dashboard-view-selected={dashboardMode==='list'} aria-label="List view" aria-pressed={dashboardMode==='list'} title="List view" on:click={()=>dashboardMode='list'}><List size={16}/></button></div>{/if}<button class="p-2 border border-slate-200 rounded-md text-slate-500" title="Show task widget" aria-label="Show task widget" on:click={enterMini}><LayoutDashboard size={16}/></button>{#if view!=='Settings'&&view!=='Projects'}<button class="bg-[#5473E6] text-white py-2 px-3 text-[13px] font-bold rounded-md flex items-center gap-1" on:click={()=>editTask()}><Plus size={14}/> New Task</button>{/if}</div></div>
      {#if view==='Dashboard'}
        <div class="dashboard-summary"><div><span>Tasks today</span><strong>{day.total}</strong></div><div><span>Completed</span><strong>{day.done}<small> / {day.total}</small></strong></div><div class="dashboard-progress-stat"><span>Daily progress</span><strong>{day.percent}%</strong><div class="dashboard-progress-track"><span style:width={`${day.percent}%`}></span></div></div></div>
        {#if error}<div class="bg-rose-50 text-rose-700 p-3 text-xs rounded-md mb-4">{error}</div>{/if}
        {#if dashboardMode==='cards'}<div class="dashboard-board">{#each dashboardColumns as column}<section aria-label={`${column.name} tasks`} class={`dashboard-column dashboard-column-${column.tone}`} class:dashboard-drop-target={dragOverStatus===column.tone} on:dragover={(event)=>{event.preventDefault();dragOverStatus=column.tone}} on:dragleave={()=>{if(dragOverStatus===column.tone)dragOverStatus=''}} on:drop={(event)=>dropDashboardTask(event,column.tone)}><header class="dashboard-column-heading"><div><span class="dashboard-column-icon">{column.icon}</span><h2>{column.name}</h2></div><span class="dashboard-column-count">{column.entries.length} {column.entries.length===1?'task':'tasks'}</span></header><div class="dashboard-card-list">{#each column.entries as entry (entry.task.id)}<article class="dashboard-task-card" class:dashboard-card-dragging={draggedTaskId===entry.task.id} draggable="true" on:dragstart={(event)=>startDashboardDrag(event,entry)} on:dragend={endDashboardDrag} style={`--task-accent: ${palette[entry.task.category]?.text||'#5473E6'}`}><button class="dashboard-card-open" on:click={()=>openResultEntry(entry)} aria-label={`Open ${entry.task.title}`}><span class="dashboard-task-meta"><span class="dashboard-task-category">{entry.task.category}</span><span>{entry.task.start} · {entry.task.duration}m</span></span><strong>{entry.task.title}</strong>{#if resultHasDetails(entry.result)}<span class="dashboard-task-preview">{richTextPreview(entry.result.output||entry.result.activity||entry.result.summary)}</span>{/if}</button><div class="dashboard-card-footer"><button class="dashboard-complete-toggle" class:dashboard-is-complete={entry.result.done} title={entry.result.done?'Mark as to do':'Mark completed'} on:click={()=>toggleDone(entry)}>{#if entry.result.done}<Check size={12}/>{:else}<span></span>{/if}</button><button class="dashboard-card-edit" title="Edit task" on:click={()=>editTask(entry.task)}><Pencil size={13}/></button><button class="dashboard-card-delete" title="Delete task" aria-label={`Delete ${entry.task.title}`} on:click={()=>deleteTask(entry.task)}><Trash2 size={13}/></button></div></article>{:else}<div class="dashboard-column-empty">No {column.name.toLowerCase()} tasks</div>{/each}</div></section>{/each}</div>{:else}
        <div class="dashboard-lists">
          <section class="dashboard-list-panel"><div class="flex items-center justify-between mb-5 border-b border-[#eef0f5]"><div class="flex gap-6">{#each ['All','Important','Notes','Links'] as f}<button class:chosen={filter===f} class="tab text-[13px] font-semibold text-slate-400 pb-4" on:click={()=>filter=f}>{f==='All'?`${day.total} All`:f}</button>{/each}</div><span class="text-[13px] text-slate-400">{day.done}/{day.total} done</span></div><div class="h-1.5 bg-[#edeafa] rounded-md mb-4 overflow-hidden"><div class="h-full bg-[#7866e0]" style:width={`${day.percent}%`}></div></div><div>{#each visibleEntries as entry (entry.task.id)}<div class="task-line group flex items-center gap-3 py-3 border-b border-[#f3f3f7]" style:background={taskCardColor(entry.task)}><button class:checked={entry.result.done} class="task-check shrink-0" on:click={()=>toggleDone(entry)} aria-label="Complete task">{#if entry.result.done}<Check size={12} strokeWidth={3}/>{/if}</button><div class="flex-1 min-w-0"><p class:completed={entry.result.done} class="text-[13px] font-semibold truncate">{entry.task.title}</p><p class="text-[12px] text-slate-400 mt-1 flex items-center gap-1"><Clock3 size={11}/>{entry.task.start} · {entry.task.duration} min</p></div><span class="category" style:background={palette[entry.task.category]?.bg||'#f3f4f6'} style:color={palette[entry.task.category]?.text||'#667085'}>{entry.task.category}</span><span class="state-pill {pill(entry)}">{status(entry)}</span><button class="row-action" title="Record result" on:click={()=>editResult(entry)}><FileText size={14}/></button><button class="row-action" title="Edit task" on:click={()=>editTask(entry.task)}><Pencil size={14}/></button><button class="row-action text-rose-400" title="Delete task" aria-label={`Delete ${entry.task.title}`} on:click={()=>deleteTask(entry.task)}><Trash2 size={14}/></button></div>{:else}<div class="py-9 text-center text-slate-400 text-xs">No activities here. Click New Task to start.</div>{/each}</div></section>
        </div>{/if}
        <section class="dashboard-upcoming"><div class="flex items-center justify-between mb-5"><h2 class="section-title-with-icon text-base font-extrabold"><img class="feature-icon" src={taskManagementIcon} alt="" aria-hidden="true"/>Upcoming Tasks</h2><span class="text-[13px] text-slate-400">Remaining today</span></div><div class="space-y-2">{#each nextEntries as entry}<button class="w-full flex items-center gap-3 px-3 py-3 bg-[#fafbfe] rounded-md text-left" style:background={taskCardColor(entry.task)} on:click={()=>editResult(entry)}><div class="h-4 w-4 rounded-sm border border-slate-300"></div><span class="flex-1 text-[13px] font-medium truncate">{entry.task.title}</span><span class="text-[12px] text-slate-400">{entry.task.start}</span><ChevronRight size={14} class="text-slate-300"/></button>{:else}<p class="text-xs text-slate-400 py-4">Everything completed for today. Great work!</p>{/each}</div></section>
      {:else if view==='Projects'}
        <section class="projects-page">
          {#if selectedProject}
            <div class="project-detail-heading"><button class="project-back-button" on:click={()=>selectedProjectId=''}><ChevronLeft size={16}/> All projects</button><div class="project-detail-actions"><button class="project-secondary-button" on:click={()=>openProjectDialog(selectedProject)}><Pencil size={14}/> Edit project</button><button class="project-danger-button" on:click={()=>deleteProject(selectedProject)}><Trash2 size={14}/> Delete project</button></div></div>
            <div class="project-detail-grid"><div class="project-detail-left">
            <section class="project-overview-card">
              <nav class="project-overview-tabs" role="tablist" aria-label="Project overview tabs"><button role="tab" aria-selected={projectOverviewTab==='level'} class:overview-tab-active={projectOverviewTab==='level'} on:click={()=>projectOverviewTab='level'}><Trophy size={14}/>Level</button><button role="tab" aria-selected={projectOverviewTab==='linearity'} class:overview-tab-active={projectOverviewTab==='linearity'} on:click={()=>projectOverviewTab='linearity'}><List size={14}/>Task Linearity</button><button role="tab" aria-selected={projectOverviewTab==='ai'} class:overview-tab-active={projectOverviewTab==='ai'} on:click={()=>projectOverviewTab='ai'}><Sparkles size={14}/>AI Overview</button></nav>
              {#if projectOverviewTab==='level'}<div class="project-tab-content"><div class="project-overview-heading"><div><span class="project-kicker">PROJECT LEVEL</span><h2>Level {projectLevel}</h2></div><span>{projectXP} XP earned</span></div><div class="project-level-bar"><div><i style:width={`${projectLevelProgress}%`}></i></div><span>{projectXP%500} / 500 XP to Level {projectLevel+1}</span></div><div class="project-overview-stats"><div><strong>{selectedProjectTasks.length}</strong><span>Tasks</span></div><div><strong>{completedProjectTasks}</strong><span>Completed</span></div><div><strong>{completedProjectObjectives}/{projectObjectives.length}</strong><span>Objectives</span></div></div></div>
              {:else if projectOverviewTab==='linearity'}<div class="project-tab-content"><div class="project-section-heading"><h2>Task linearity</h2></div>{#if projectEvaluation?.tasks?.length}<ProjectLinearityChart points={linearityChartPoints}/><div class="linearity-reasons">{#each projectEvaluation.tasks as item (`${item.taskId}-${item.date}`)}{@const matchingTask=selectedProjectTasks.find(task=>task.id===item.taskId)}<article><div><strong>{matchingTask?.title||'Project task'}</strong><small>{item.date} · {item.score}/100</small></div><p>{item.reason}</p></article>{/each}</div>{:else}<div class="project-empty-state"><strong>No scores yet</strong></div>{/if}</div>
              {:else}<div class="project-tab-content"><div class="project-ai-heading"><span class="project-ai-icon"><Sparkles size={18}/></span><div><h2>AI Overview</h2></div></div>{#if projectEvaluation}<div class="project-ai-summary"><strong>Project direction</strong><p>{projectEvaluation.overview}</p></div>{#if projectEvaluation.suggestions?.length}<div class="project-ai-suggestions"><strong>Next actions</strong>{#each projectEvaluation.suggestions as suggestion,index}<article><span>{index+1}</span><p>{suggestion}</p></article>{/each}</div>{/if}<p class="project-ai-updated">Last evaluated {selectedProject.evaluatedAt?new Date(selectedProject.evaluatedAt).toLocaleString():'recently'} · {projectEvaluation.tasks?.length||0} results scored</p>{:else}<div class="project-ai-empty"><strong>No AI overview yet</strong></div>{/if}{#if projectEvaluationError}<p class="project-error">{projectEvaluationError}</p>{/if}<button class="project-primary-button project-ai-run" on:click={evaluateProjectOverview} disabled={projectEvaluating}><Sparkles size={15}/>{projectEvaluating?'Evaluating…':projectEvaluation?'Evaluate again':'Evaluate with AI'}</button></div>{/if}
            </section>
            <section class="project-objectives-panel"><div class="project-objectives-heading"><div><h2>Objectives</h2></div><div class="project-objectives-progress"><span>{completedProjectObjectives}/{projectObjectives.length} complete</span><div><i style:width={`${projectObjectives.length?completedProjectObjectives/projectObjectives.length*100:0}%`}></i></div></div><button class="project-primary-button" on:click={openObjectiveDialog}><Plus size={15}/> Create objective</button></div>{#if projectObjectives.length}<div class="project-objective-list">{#each projectObjectives as objective (objective.id)}<article class="project-objective-row"><input type="checkbox" checked={objective.done} aria-label={`Mark ${objective.title} complete`} on:change={(event)=>toggleProjectObjective(objective,event.currentTarget.checked)}/><span class:project-objective-done={objective.done}>{objective.title}</span><button class="project-objective-delete" title="Delete objective" aria-label={`Delete ${objective.title}`} on:click={()=>deleteProjectObjective(objective)}><Trash2 size={14}/></button></article>{/each}</div>{:else}<div class="project-objectives-empty"><Check size={16}/><span>No objectives yet.</span></div>{/if}</section></div>
            <section class="project-tasks-panel"><div class="project-section-heading"><div><h2>Project tasks</h2></div><button class="project-primary-button" on:click={()=>editTask(null,selectedProject.id)}><Plus size={15}/> Create task</button></div>
              {#if selectedProjectTasks.length}<div class="project-task-list">{#each selectedProjectTasks as task (task.id)}<article class="project-task-row"><span class="project-task-color" style:background={task.color||palette[task.category]?.text||'#5473E6'}></span><div class="project-task-info"><strong>{task.title}</strong><span>{task.date} · {task.start} · {task.duration} min · {task.repeat==='none'?'One time':task.repeat}</span></div><span class="category" style:background={palette[task.category]?.bg||'#f3f4f6'} style:color={palette[task.category]?.text||'#667085'}>{task.category}</span><button class="project-icon-button" title="Edit scheduled task" aria-label={`Edit ${task.title}`} on:click={()=>editTask(task)}><Pencil size={14}/></button><button class="project-icon-button project-remove-button" title="Remove from project; keep the task scheduled" aria-label={`Remove ${task.title} from project`} on:click={()=>removeTaskFromProject(task)}><X size={15}/></button></article>{/each}</div>{:else}<div class="project-empty-state"><strong>No tasks in this project yet</strong></div>{/if}
              {#if projectCandidateTasks.length}<form class="project-add-existing" on:submit|preventDefault={assignExistingTaskToProject}><label><span>Add an existing scheduled task</span><select bind:value={projectTaskToAdd} required><option value="" disabled>Select a task to add or move</option>{#each projectCandidateTasks as task (task.id)}<option value={task.id}>{task.title}{task.projectId?` · currently in ${projects.find(project=>project.id===task.projectId)?.name||'another project'}`:''}</option>{/each}</select></label><button class="project-secondary-button" type="submit" disabled={!projectTaskToAdd}><Plus size={14}/> Add to project</button></form>{/if}
            </section></div>
          {:else}
            <div class="project-list-heading"><div><span class="project-kicker">YOUR WORKSPACES</span><h2>Projects</h2><p>Bring related schedule activities and objectives together.</p></div><button class="project-primary-button" on:click={()=>openProjectDialog()}><Plus size={15}/> New project</button></div>
            {#if error}<p class="project-error">{error}</p>{/if}
            {#if projects.length}<div class="project-card-grid">{#each projects as project (project.id)}<button class="project-card" on:click={()=>openProject(project)} aria-label={`Open project ${project.name}`}><span class="project-folder-scene" aria-hidden="true"><span class="project-folder"><span class="project-folder-back"></span><span class="project-folder-paper">{#if project.objectives?.length}<span class="project-folder-objectives">{#each project.objectives as objective (objective.id)}<small>{objective.title}</small>{/each}</span>{:else}<small class="project-folder-empty">No objectives yet</small>{/if}</span><span class="project-folder-front"><span>{project.name}</span><span class="project-folder-level-ring" style={`--level-progress:${Math.max(0,Math.min(100,((project.xp||0)%500)/5))}%`}><span>{project.level||1}</span></span></span><span class="project-folder-flap"></span></span></span></button>{/each}</div>{:else}<div class="project-empty-state project-list-empty"><FolderKanban size={25}/><strong>No projects yet</strong><p>Create a project, then add objectives and schedule tasks.</p><button class="project-primary-button" on:click={()=>openProjectDialog()}><Plus size={15}/> Create your first project</button></div>{/if}
          {/if}
        </section>
      {:else if view==='Productivity Matrix'}
        <section class="productivity-page">
          <div class="productivity-toolbar"><div><strong>Growth timeline</strong><small>Compare this period with the immediately preceding period of equal length.</small></div><div class="productivity-range">{#each [{value:'7',label:'7 days'},{value:'30',label:'30 days'},{value:'90',label:'90 days'},{value:'custom',label:'Custom'}] as option}<button class:range-active={productivityRange===option.value} on:click={()=>setProductivityRange(option.value)}>{option.label}</button>{/each}</div></div>
          {#if productivityRange==='custom'}<div class="productivity-custom-range"><label>From<input type="date" bind:value={productivityStart} max={productivityEnd}/></label><label>To<input type="date" bind:value={productivityEnd} min={productivityStart}/></label></div>{/if}
          <div class="productivity-chart-summary"><div><strong>{productivity.growthScore===null?'—':`${productivity.growthScore}`}</strong><span>Growth score</span></div><div><strong>{productivity.sessions}</strong><span>Sessions</span></div><div><strong>{productivity.activeDays}</strong><span>Active days</span></div><div><strong>{productivity.outputCount}</strong><span>Reported outputs</span></div><div><strong>{productivity.activityPoints} / {productivity.growthPoints}</strong><span>AP / GP</span></div></div>
          <div class="productivity-chart-grid">
            <section class="productivity-chart-card productivity-chart-panel">
              <header><div><h2>{productivityChartTab==='cumulative'?'Cumulative GP':productivityChartTab==='average'?'Daily growth':'GP by task'}</h2><p>{productivityChartTab==='average'?'GP earned each day · ':''}{productivityBounds.start} — {productivityBounds.end}</p></div><span>{productivityChartTab==='average'?'GP/day':'GP'}</span></header>
              <div class="productivity-chart-tabs" role="tablist" aria-label="Growth charts">
                <button type="button" role="tab" aria-selected={productivityChartTab==='cumulative'} class:productivity-chart-tab-active={productivityChartTab==='cumulative'} on:click={()=>productivityChartTab='cumulative'}>Cumulative GP</button>
                <button type="button" role="tab" aria-selected={productivityChartTab==='average'} class:productivity-chart-tab-active={productivityChartTab==='average'} on:click={()=>productivityChartTab='average'}>Daily growth</button>
                <button type="button" role="tab" aria-selected={productivityChartTab==='tasks'} class:productivity-chart-tab-active={productivityChartTab==='tasks'} on:click={()=>productivityChartTab='tasks'}>GP by task</button>
              </div>
              {#if productivityChartTab==='cumulative'||productivityChartTab==='average'}
                {#if productivityTrend.some(bucket=>bucket.growthPoints)}<ProductivityTrendChart trend={productivityTrend} mode={productivityChartTab}/>{:else}<p class="productivity-chart-empty">Log activity results with outputs to earn Growth Points.</p>{/if}
              {:else if productivityTrend.some(bucket=>bucket.growthPoints)}
                <ProductivityTrendChart trend={productivityTrend} mode="tasks"/>
              {:else}<p class="productivity-chart-empty">No Growth Points recorded in this period yet.</p>{/if}
            </section>
          </div>
          <p class="productivity-scoring-note">Before AI Evaluate, GP is calculated from reported outputs. After evaluation, AI replaces that session’s GP with a 0–100 estimate based on the recorded output and summary; re-evaluation replaces the previous value.</p>
        </section>
      {:else if view==='Calendar'}
        <div class="calendar-panel">
          <div class="flex items-center justify-between mb-5"><div><h2 class="text-lg font-extrabold capitalize">{calendarTitle}</h2><p class="text-[13px] text-slate-400 mt-1">Select a date to view its schedule</p></div><div class="flex items-center gap-2"><button class="calendar-nav" aria-label="Previous month" on:click={()=>shiftCalendarMonth(-1)}><ChevronLeft size={16}/></button><button class="calendar-today" on:click={()=>selectCalendarDate(today())}>Today</button><button class="calendar-nav" aria-label="Next month" on:click={()=>shiftCalendarMonth(1)}><ChevronRight size={16}/></button></div></div>
          <div class="calendar-grid calendar-weekdays">{#each ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as weekday}<div>{weekday}</div>{/each}</div>
          <div class="calendar-grid">{#each calendarCells as cell}<button class="calendar-cell" class:outside={!cell.current} class:calendar-selected={cell.key===selectedDate} class:calendar-today={cell.today} on:click={()=>selectCalendarDate(cell.key)}><span class="calendar-number">{cell.day}</span>{#if cell.entries.length}<div class="calendar-dots">{#each cell.entries.slice(0,3) as entry}<span style:background={entry.color||palette[entry.category]?.text||'#5473E6'} title={entry.title}></span>{/each}{#if cell.entries.length>3}<small>+{cell.entries.length-3}</small>{/if}</div>{/if}</button>{/each}</div>
          <div class="mt-7 border-t border-slate-100 pt-5"><div class="flex items-center justify-between mb-3"><h3 class="text-sm font-extrabold">{new Date(selectedDate+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',day:'numeric',month:'long'})}</h3><span class="text-[12px] text-slate-400">{selectedMonthEntries.length} schedule(s)</span></div>{#each selectedMonthEntries as entry}<button class="calendar-agenda" on:click={()=>openResultEntry(entry)}><span class="calendar-agenda-time">{entry.task.start}</span><span class="flex-1 min-w-0"><strong class="block truncate">{entry.task.title}</strong><small>{entry.task.category} · {entry.task.duration} min</small></span><ChevronRight size={15} class="text-slate-300"/></button>{:else}<div class="py-8 text-center text-xs text-slate-400">No schedule for this date yet.</div>{/each}</div>
        </div>
      {:else if view==='Settings'}
        <section class="settings-panel" class:settings-expanded={aiSettingsExpanded}>
          <div class="settings-panel-heading">
            <button class="settings-panel-trigger" aria-expanded={aiSettingsExpanded} on:click={()=>aiSettingsExpanded=!aiSettingsExpanded}>
              <span class="settings-panel-icon"><Sparkles size={18}/></span>
              <span class="settings-panel-title"><strong>AI Assistant</strong><small>{defaultAIConnected()?`Default: ${aiProviders.find(item=>item.id===aiSettings.defaultProvider)?.name} · Ready to evaluate`:'Connect a provider to evaluate activity results'}</small></span>
              <ChevronRight size={17} class={aiSettingsExpanded?'settings-chevron-open':''}/>
            </button>
            <button class="settings-toggle" class:settings-toggle-on={defaultAIConnected()} role="switch" aria-checked={defaultAIConnected()} aria-label={defaultAIConnected()?'Disconnect default AI provider':'Open AI Assistant settings'} disabled={aiBusy} on:click={toggleAISettings}><span></span></button>
          </div>
          {#if aiSettingsExpanded}<div class="settings-dropdown"><div class="settings-dropdown-inner">
            <label class="flat-label settings-provider-select">AI Provider<select class="flat-input" bind:value={aiProviderDraft} disabled={aiBusy} on:change={chooseAIProvider}>{#each aiProviders as provider}<option value={provider.id}>{provider.name}{#if provider.id===aiSettings.defaultProvider} · Default{/if}{#if aiProviderConnected(provider.id)} · Connected{/if}</option>{/each}</select></label>
            {#if aiProviderConnected()}<div class="settings-connection settings-connected"><span class="settings-connection-dot"></span>Connected{#if aiSettings.defaultProvider===aiProviderDraft} · Default{/if}</div><div class="settings-form-row"><label class="flat-label settings-key-field">Model ID<input class="flat-input" type="text" autocomplete="off" spellcheck="false" bind:value={aiModelInput} placeholder="Enter a model ID" on:keydown={(event)=>event.key==='Enter'&&saveAIProviderModel()}/></label><button class="flat-btn flat-btn-primary settings-connect" disabled={aiBusy||!aiModelInput.trim()||aiModelInput===aiSettings.providers[aiProviderDraft].model} on:click={saveAIProviderModel}>{aiBusy?'Checking…':'Save Model'}</button></div><p class="settings-key-note">Enter a model ID available to your {aiProviders.find(item=>item.id===aiProviderDraft)?.name} account. The model will be checked before it is saved. Your API key remains encrypted on this device.</p><button class="flat-btn flat-btn-ghost settings-disconnect" disabled={aiBusy} on:click={disconnectAI}>{aiBusy?'Disconnecting…':'Disconnect '+(aiProviders.find(item=>item.id===aiProviderDraft)?.name||'AI')}</button>
            {:else}<div class="settings-form-row" style="display:flex;align-items:flex-end;gap:12px"><label class="flat-label settings-key-field" style="flex:1;min-width:0">{aiProviders.find(item=>item.id===aiProviderDraft)?.name} API Key<input class="flat-input" type="password" autocomplete="off" spellcheck="false" bind:value={aiKeyInput} placeholder="Paste API key" on:keydown={(event)=>event.key==='Enter'&&connectAI()}/></label><button class="flat-btn flat-btn-primary settings-connect" style="flex:0 0 auto;white-space:nowrap" disabled={aiBusy||!aiKeyInput.trim()} on:click={connectAI}><Sparkles size={15}/>{aiBusy?'Connecting…':'Connect '+(aiProviders.find(item=>item.id===aiProviderDraft)?.name||'AI')}</button></div><p class="settings-key-note">Your key is checked and saved encrypted on this device. Activity details are only sent to the selected provider when you click AI Evaluate.</p>{/if}
          </div></div>{/if}
        </section>
        <section class="settings-panel settings-profile-panel">
          <div class="settings-panel-heading"><span class="settings-panel-icon"><BookOpen size={18}/></span><span class="settings-panel-title"><strong>Your name</strong><small>{userName?`DailyFlow will greet you as ${userName}`:'Add your name to personalize your dashboard greeting'}</small></span></div>
          <div class="settings-name-content"><label class="flat-label">Name<input class="flat-input" type="text" maxlength="40" autocomplete="given-name" bind:value={nameDraft} placeholder="Your name" on:keydown={(event)=>event.key==='Enter'&&saveUserName()}/></label><button class="flat-btn flat-btn-primary" disabled={nameSaving||!nameDraft.trim()||nameDraft.trim()===userName} on:click={saveUserName}>{nameSaving?'Saving…':'Save name'}</button></div>
        </section>
        <section class="settings-panel settings-tray-panel">
          <div class="settings-panel-heading"><span class="settings-panel-icon"><Power size={18}/></span><span class="settings-panel-title"><strong>Start with Windows</strong><small>{autoStartEnabled?'DailyFlow starts automatically when you sign in':'DailyFlow starts only when you open it'}</small></span><button class="settings-toggle" class:settings-toggle-on={autoStartEnabled} role="switch" aria-checked={autoStartEnabled} aria-label="Start DailyFlow automatically with Windows" disabled={autoStartBusy} on:click={toggleAutoStart}><span></span></button></div>
          <div class="settings-tray-content"><p>Launch DailyFlow when you sign in to Windows. The task widget will appear automatically; turn this off anytime to remove it from startup.</p></div>
        </section>
        <section class="settings-panel settings-tray-panel">
          <div class="settings-panel-heading"><span class="settings-panel-icon"><LayoutDashboard size={18}/></span><span class="settings-panel-title"><strong>System tray icon</strong><small>{trayIconEnabled?'DailyFlow icon is shown in the system tray':'DailyFlow icon is hidden from the system tray'}</small></span><button class="settings-toggle" class:settings-toggle-on={trayIconEnabled} role="switch" aria-checked={trayIconEnabled} aria-label="Show DailyFlow in the system tray" disabled={traySettingsBusy} on:click={toggleTrayIcon}><span></span></button></div>
          <div class="settings-tray-content"><p>Turn this on to keep a DailyFlow icon in the notification area. To place it specifically inside “Show hidden icons”, drag the icon there once; Windows remembers its position.</p></div>
        </section>
      {:else if view==='All activities'}
        <div class="activity-log">
          <div class="activity-log-toolbar"><div class="activity-filter-tabs">{#each ['All','Completed','With details'] as option}<button class:activity-filter-active={activityFilter===option} on:click={()=>activityFilter=option}>{option}</button>{/each}<span class="activity-count">{activityEntries.length} records</span></div><label class="activity-search"><Search size={15}/><input bind:value={activitySearch} placeholder="Search task or activity..." aria-label="Search activity log"/></label></div>
          {#if error}<div class="bg-rose-50 text-rose-700 p-3 text-xs rounded-md mb-4">{error}</div>{/if}
          {#each activityGroups as group (group.date)}
            <section class="activity-date-group"><div class="activity-date-heading"><span>{activityDateLabel(group.date)}</span><small>{group.entries.length} {group.entries.length===1?'record':'records'}{#if activityDateLabel(group.date)!=='Today'&&activityDateLabel(group.date)!=='Yesterday'} · {new Date(group.date+'T12:00:00').toLocaleDateString('en-US',{day:'numeric',month:'short',year:'numeric'})}{/if}</small></div>
              <div class="activity-timeline">{#each group.entries as entry,i (entry.task.id+entry.result.date)}<div class="activity-entry"><span class="activity-time">{entry.task.start}</span><span class="activity-track"><span class="activity-marker" style:background={entry.task.color||'#5473E6'}></span>{#if i<group.entries.length-1}<span class="activity-connector"></span>{/if}</span><details class="activity-card" class:activity-card-ai-evaluated={entry.result.aiScore>0} style:background={scheduleCardColor(entry.task,entry.result.date)}><summary class="activity-card-summary"><span class="activity-card-heading"><strong>{entry.task.title}</strong><span class="category" style:background={palette[entry.task.category]?.bg||'#f3f4f6'} style:color={palette[entry.task.category]?.text||'#667085'}>{entry.task.category}</span><span class="activity-status" class:activity-complete={entry.result.done}>{entry.result.done?'Completed':'Recorded'}</span>{#if entry.result.aiScore>0}<span class="activity-ai-score"><Trophy size={12}/>{entry.result.aiScore}/100</span>{/if}</span><ChevronRight size={15} class="activity-toggle-icon"/></summary><div class="activity-card-details"><div class="activity-card-content">{#if entry.result.activity}<span class="activity-detail-label">What did you do?</span><span class="activity-detail-list">{#each resultLines(entry.result.activity) as line}<span>• {line}</span>{/each}</span>{/if}{#if entry.result.output}<span class="activity-detail-label">Output / deliverable</span><span class="activity-detail-list">{#each resultLines(entry.result.output) as line}<span>• {line}</span>{/each}</span>{/if}{#if entry.result.summary}<span class="activity-detail-label">Summary</span><span class="activity-summary">{richTextPreview(entry.result.summary)}</span>{/if}{#if !resultHasDetails(entry.result)}<p class="activity-no-details">Task marked complete. No additional notes were recorded.</p>{/if}</div><div class="activity-card-footer"><span>{entry.task.start} · {entry.task.duration} min</span><div class="activity-card-actions"><button type="button" on:click={()=>openResultEntry(entry)}>Open full result</button><button type="button" class="activity-delete-button" title="Delete activity log" aria-label={`Delete activity log for ${entry.task.title} on ${entry.result.date}`} on:click={()=>deleteActivityResult(entry)}><Trash2 size={13}/>Delete</button></div></div></div></details></div>{/each}</div>
            </section>
          {:else}<div class="activity-empty"><span class="activity-empty-icon"><Archive size={20}/></span><strong>No activity records yet</strong><p>Record an Activity Result or mark a task complete to see it here.</p><button class="bg-[#5473E6] text-white px-3 py-2 rounded-md text-[13px] font-bold" on:click={()=>navigate('Today')}>View today’s tasks</button></div>{/each}
        </div>
      {:else}
      <div class="flex items-center justify-between mb-5 border-b border-[#eef0f5]"><div class="flex gap-6">{#each ['All','Important','Notes','Links'] as f}<button class:chosen={filter===f} class="tab text-[13px] font-semibold text-slate-400 pb-4" on:click={()=>filter=f}>{f==='All'?`${day.total} All`:f}</button>{/each}</div><span class="text-[13px] text-slate-400">{day.done}/{day.total} done</span></div>
      <div class="h-1.5 bg-[#edeafa] rounded-md mb-7 overflow-hidden"><div class="h-full bg-[#7866e0]" style:width="{day.percent}%"></div></div>
      {#if error}<div class="bg-rose-50 text-rose-700 p-3 text-xs rounded-md mb-4">{error}</div>{/if}
      <div class="space-y-1 min-h-[220px]">
        {#each visibleEntries as entry (entry.task.id)}
          <div class="task-line group flex items-center gap-3 py-3 border-b border-[#f3f3f7]" style:background={taskCardColor(entry.task)}><button class:checked={entry.result.done} class="task-check shrink-0" on:click={()=>toggleDone(entry)} disabled={view==='All activities'} aria-label="Complete task">{#if entry.result.done}<Check size={12} strokeWidth={3}/>{/if}</button><div class="flex-1 min-w-0"><p class:completed={entry.result.done} class="text-[13px] font-semibold truncate">{entry.task.title}</p><p class="text-[12px] text-slate-400 mt-1 flex items-center gap-1"><Clock3 size={11}/>{entry.task.start} · {entry.task.duration} min <span class="mx-1">·</span>{entry.task.repeat==='none'?'One-time':entry.task.repeat}</p></div><span class="category" style:background={palette[entry.task.category]?.bg||'#f3f4f6'} style:color={palette[entry.task.category]?.text||'#667085'}>{entry.task.category}</span><span class="state-pill {pill(entry)}">{status(entry)}</span><button class="row-action" title="Record result" on:click={()=>editResult(entry)} disabled={view==='All activities'}><FileText size={14}/></button><button class="row-action" title="Edit task" on:click={()=>editTask(entry.task)}><Pencil size={14}/></button><button class="row-action text-rose-400" title="Delete task" on:click={()=>deleteTask(entry.task)}><Trash2 size={14}/></button></div>
        {:else}<div class="py-14 text-center text-slate-400 text-xs">No activities here. Click New Task to start.</div>{/each}
      </div>
      <div class="mt-9 flex items-center justify-between"><h2 class="section-title-with-icon text-base font-extrabold"><img class="feature-icon" src={taskManagementIcon} alt="" aria-hidden="true"/>Upcoming Tasks</h2><span class="text-[13px] text-slate-400">Remaining today</span></div>
      <div class="mt-4 space-y-2">{#each nextEntries as entry}<button class="w-full flex items-center gap-3 px-3 py-3 bg-[#fafbfe] rounded-md text-left" style:background={taskCardColor(entry.task)} on:click={()=>editResult(entry)}><div class="h-4 w-4 rounded-sm border border-slate-300"></div><span class="flex-1 text-[13px] font-medium truncate">{entry.task.title}</span><span class="text-[12px] text-slate-400">{entry.task.start}</span><ChevronRight size={14} class="text-slate-300"/></button>{:else}<p class="text-xs text-slate-400 py-4">Everything completed for today. Great work!</p>{/each}</div>
      {/if}
    </main>
    {#if view!=='All activities'&&view!=='Projects'}<section class="w-[300px] xl:w-[335px] shrink-0 bg-[#fff] border-l border-[#edf0f5] px-7 py-9">
      <div class="flex items-center justify-between mb-9"><div class="flex items-center gap-2 text-[13px] text-slate-400"><img class="feature-icon feature-icon-overview" src={productivityAnalyticsIcon} alt="" aria-hidden="true"/>DAILY OVERVIEW</div><div class="w-9 h-9 bg-[#45c9ac] text-white rounded-md grid place-items-center font-extrabold text-sm">{day.done}</div></div>
      <h2 class="section-title-with-icon text-[15px] mb-4"><img class="feature-icon" src={dailyScheduleIcon} alt="" aria-hidden="true"/>Schedule & Focus</h2>
          <div class="space-y-3">{#each day.entries.slice(0,4) as entry,i}<article class="schedule-card" style:background={scheduleCardColor(entry.task,selectedDate)}><button class="schedule-card-main" on:click={()=>openResultEntry(entry)} aria-label={`Open ${entry.task.title}`}><div class="flex justify-between text-[12px] opacity-60"><span>{entry.task.start} · {entry.task.duration} MIN</span></div><div class="font-bold text-[12px] mt-2 leading-relaxed">{entry.task.title}</div><div class="flex items-center justify-between mt-5"><span class="text-[12px] opacity-65">{entry.task.category}</span><span class="bg-white/65 px-2 py-1 rounded-md text-[12px] font-semibold">{status(entry)}</span></div></button><button class="schedule-card-project-action" class:schedule-card-project-linked={entry.task.projectId} type="button" title="Add or move task to a project" aria-label={`Add ${entry.task.title} to a project`} on:click={()=>openScheduleProjectPicker(entry)}>{#if entry.task.projectId}<FolderKanban size={15}/>{:else}<FolderPlus size={15}/>{/if}</button></article>{:else}<div class="text-xs text-slate-400 rounded-md bg-slate-50 p-4">Your schedule will appear here.</div>{/each}</div>
      <div class="mt-8 flex items-center justify-between"><h2 class="section-title-with-icon text-[14px] font-extrabold"><img class="feature-icon" src={habitTrackerIcon} alt="" aria-hidden="true"/>Recent Results</h2><span class="text-[12px] text-slate-400">{recordedResultCount} / {day.total}</span></div>
      <div class="mt-3 space-y-2">{#each day.entries.filter(e=>e.result.activity||e.result.output||e.result.summary).slice(0,3) as entry}<button class="text-left block w-full border border-[#eef0f5] rounded-md p-3" on:click={()=>openResultEntry(entry)}><strong class="text-[13px] block truncate">{entry.task.title}</strong>{#if entry.result.output}<p class="text-[12px] text-slate-500 mt-2">Output: {richTextPreview(entry.result.output)}</p>{/if}{#if entry.result.summary}<p class="text-[12px] text-slate-400 mt-1 line-clamp-2">{richTextPreview(entry.result.summary)}</p>{/if}</button>{:else}<p class="text-[13px] text-slate-400 leading-relaxed">Record an activity result to see your daily learning and work summaries.</p>{/each}</div>
    </section>{/if}
  </div>
{/if}

{#if showNamePrompt && !mini}<div class="modal-backdrop action-backdrop first-run-name-backdrop" role="presentation"><form class="modal-panel first-run-name-dialog" role="dialog" aria-modal="true" aria-labelledby="first-run-name-title" on:submit|preventDefault={saveUserName}><span class="first-run-name-icon"><Check size={22}/></span><h2 id="first-run-name-title">Welcome to DailyFlow</h2><p>Input Your Name so your dashboard can greet you personally.</p><label class="flat-label">Your name<input class="flat-input" type="text" maxlength="40" autocomplete="given-name" bind:value={nameDraft} placeholder="e.g. Lusi" autofocus required/></label>{#if error}<small class="first-run-name-error">{error}</small>{/if}<button class="flat-btn flat-btn-primary" type="submit" disabled={nameSaving||!nameDraft.trim()}>{nameSaving?'Saving…':'Continue'}</button></form></div>{/if}
{#if objectiveDialog}<div class="modal-backdrop action-backdrop" role="presentation"><form class="modal-panel objective-dialog" role="dialog" aria-modal="true" aria-labelledby="objective-dialog-title" on:submit|preventDefault={saveObjective}><div class="project-dialog-heading"><span class="project-card-icon"><Check size={18}/></span><div><h2 id="objective-dialog-title">Create objective</h2><p>Add a milestone for {selectedProject?.name||'this project'}.</p></div><button type="button" class="task-close" aria-label="Close" on:click={closeObjectiveDialog}><X size={18}/></button></div><label class="flat-label">Objective<input class="flat-input" type="text" maxlength="180" bind:value={editingObjective.title} placeholder="e.g. Complete the first working prototype" required autofocus/></label>{#if error}<small class="project-error">{error}</small>{/if}<div class="project-dialog-footer"><button class="project-secondary-button" type="button" on:click={closeObjectiveDialog}>Cancel</button><button class="project-primary-button" type="submit"><Plus size={15}/> Save objective</button></div></form></div>{/if}{#if scheduleProjectTask}<div class="modal-backdrop action-backdrop" role="presentation" on:click={()=>scheduleProjectTask=null}><div class="modal-panel schedule-project-picker" role="dialog" aria-modal="true" aria-labelledby="schedule-project-picker-title" on:click|stopPropagation><div class="project-dialog-heading"><span class="project-card-icon"><FolderPlus size={18}/></span><div><h2 id="schedule-project-picker-title">Add task to project</h2><p>{scheduleProjectTask.task.title}</p></div><button type="button" class="task-close" aria-label="Close" on:click={()=>scheduleProjectTask=null}><X size={18}/></button></div>{#if projects.length}<div class="schedule-project-options">{#each projects as project (project.id)}<button type="button" class:schedule-project-current={scheduleProjectTask.task.projectId===project.id} on:click={()=>assignScheduleTaskToProject(project)}><span><strong>{project.name}</strong></span>{#if scheduleProjectTask.task.projectId===project.id}<b>Current project</b><ChevronRight size={15}/>{:else}<ChevronRight size={15}/>{/if}</button>{/each}</div>{:else}<div class="project-empty-state schedule-project-empty"><FolderKanban size={23}/><strong>No projects yet</strong><p>Create a project, then this schedule task will be added to it.</p></div>{/if}<div class="schedule-project-picker-footer"><button class="project-secondary-button" type="button" on:click={createProjectForScheduleTask}><Plus size={14}/> Create a new project</button><button class="project-secondary-button" type="button" on:click={()=>scheduleProjectTask=null}>Cancel</button></div></div></div>{/if}{#if projectDialog}<div class="modal-backdrop action-backdrop" role="presentation"><form class="modal-panel project-dialog" role="dialog" aria-modal="true" aria-labelledby="project-dialog-title" on:submit|preventDefault={saveProject}><div class="project-dialog-heading"><span class="project-card-icon"><FolderKanban size={18}/></span><div><h2 id="project-dialog-title">{editingProject.id?'Edit project':'Create project'}</h2><p>Group schedule tasks and objectives in this project.</p></div><button type="button" class="task-close" aria-label="Close" on:click={closeProjectDialog}><X size={18}/></button></div><label class="flat-label">Project name<input class="flat-input" type="text" maxlength="120" bind:value={editingProject.name} placeholder="e.g. Launch portfolio site" required autofocus/></label>{#if error}<small class="project-error">{error}</small>{/if}<div class="project-dialog-footer"><button class="project-secondary-button" type="button" on:click={closeProjectDialog}>Cancel</button><button class="project-primary-button" type="submit"><Check size={15}/> Save project</button></div></form></div>{/if}
{#if taskDialog}<div class="modal-backdrop task-backdrop" role="presentation"><form class="modal-panel task-modal" on:submit|preventDefault={saveTask}>
  <div class="task-modal-heading"><div class="task-heading-content"><div class="task-heading-icon"><Pencil size={19}/></div><h2>{editing.id?'Edit Task':'New Task'}</h2></div><button type="button" class="task-close" aria-label="Close" on:click={closeTaskDialog}><X size={18}/></button></div>
  <div class="task-form-body">
    <label class="flat-label">Task name<input required maxlength="140" class="flat-input task-input" bind:value={editing.title} placeholder="What will you work on?"/></label>
    <fieldset class="category-field"><legend class="flat-label">Category</legend><div class="category-options">{#each categories as c}<button type="button" class="category-option" class:category-active={editing.category===c} style:--category-color={palette[c].text} style:--category-bg={palette[c].bg} aria-pressed={editing.category===c} on:click={()=>editing.category=c}><span class="category-option-dot" style:background={palette[c].text}></span>{c}{#if editing.category===c}<Check size={14}/>{/if}</button>{/each}</div></fieldset>
    <label class="flat-label">Project (optional)<select class="flat-input task-input" bind:value={editing.projectId}><option value="">No project</option>{#each projects as project (project.id)}<option value={project.id}>{project.name}</option>{/each}</select></label>
    <fieldset class="card-color-field"><legend class="flat-label">Card color</legend><div class="card-color-options">{#each cardColors as color,i}<button type="button" class="card-color-swatch" class:card-color-selected={editing.color===color} style:background={color} title="Color {i+1}" aria-label="Choose card color {i+1}" aria-pressed={editing.color===color} on:click={()=>editing.color=color}>{#if editing.color===color}<Check size={14}/>{/if}</button>{/each}<label class="custom-color-swatch" class:card-color-selected={!cardColors.includes(editing.color)} title="Custom color" aria-label="Choose custom card color"><input type="color" bind:value={editing.color} aria-label="Choose custom card color"/><Plus size={15}/></label></div></fieldset>
    <div class="task-fields-row"><div class="flat-label task-date-field">Date<button type="button" class="date-trigger" aria-expanded={datePickerOpen} on:click={()=>datePickerOpen=!datePickerOpen}><CalendarDays size={16} class="date-calendar-icon"/><span>{new Date(editing.date+'T12:00:00').toLocaleDateString('en-US',{day:'numeric',month:'long',year:'numeric'})}</span><ChevronRight size={15} class="date-trigger-chevron"/></button>{#if datePickerOpen}<div class="date-picker"><div class="date-picker-header"><button type="button" aria-label="Previous month" on:click={()=>shiftTaskDateMonth(-1)}><ChevronLeft size={15}/></button><strong>{taskDateTitle}</strong><button type="button" aria-label="Next month" on:click={()=>shiftTaskDateMonth(1)}><ChevronRight size={15}/></button></div><div class="date-picker-grid date-picker-weekdays">{#each ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as weekday}<span>{weekday}</span>{/each}</div><div class="date-picker-grid">{#each taskDateCells as cell}<button type="button" class="date-picker-day" class:date-outside={!cell.current} class:date-picked={editing.date===cell.key} class:date-today={cell.key===today()} on:click={()=>chooseTaskDate(cell.key)}>{cell.day}</button>{/each}</div><button type="button" class="date-today-link" on:click={()=>chooseTaskDate(today())}>Today</button></div>{/if}</div>
      <div class="flat-label task-time-field">Start time<button type="button" class="date-trigger time-trigger" aria-expanded={timePickerOpen} on:click={openTimePicker}><Clock size={16} class="date-calendar-icon"/><span>{editing.start}</span><ChevronRight size={15} class="date-trigger-chevron"/></button>{#if timePickerOpen}<div class="time-picker"><div class="time-picker-display"><div class="time-picker-column"><button type="button" aria-label="Hour up" on:click={()=>adjustTime('hour',1)}><Plus size={15}/></button><strong>{String(timeDraftHour).padStart(2,'0')}</strong><button type="button" aria-label="Hour down" on:click={()=>adjustTime('hour',-1)}><Minus size={15}/></button><small>HOUR</small></div><b>:</b><div class="time-picker-column"><button type="button" aria-label="Minute up" on:click={()=>adjustTime('minute',1)}><Plus size={15}/></button><strong>{String(timeDraftMinute).padStart(2,'0')}</strong><button type="button" aria-label="Minute down" on:click={()=>adjustTime('minute',-1)}><Minus size={15}/></button><small>MIN</small></div></div><button type="button" class="time-confirm" on:click={commitTimePicker}>Set time</button></div>{/if}</div></div>
    <label class="flat-label duration-label">Duration (minutes)<div class="duration-control"><input required type="number" min="1" max="1440" bind:value={editing.duration}/><span>minutes</span></div></label>
    <fieldset class="repeat-field"><legend class="flat-label">Repeat</legend><div class="repeat-options">{#each [{value:'none',label:'Does not repeat',detail:'One time'},{value:'daily',label:'Daily',detail:'Every day'},{value:'weekdays',label:'Weekdays',detail:'Mon – Fri'},{value:'weekly',label:'Weekly',detail:'Same day each week'},{value:'custom',label:'Custom',detail:'Choose days'}] as option}<button type="button" class="repeat-option" class:repeat-active={editing.repeat===option.value} aria-pressed={editing.repeat===option.value} on:click={()=>setRepeat(option.value)}><span class="repeat-radio"></span><span><strong>{option.label}</strong><small>{option.detail}</small></span></button>{/each}</div></fieldset>
    {#if editing.repeat==='custom'}<div class="custom-weekdays"><span class="flat-label">Repeat on</span><div class="flex gap-2 flex-wrap">{#each [{n:1,s:'Mon'},{n:2,s:'Tue'},{n:3,s:'Wed'},{n:4,s:'Thu'},{n:5,s:'Fri'},{n:6,s:'Sat'},{n:0,s:'Sun'}] as d}<button type="button" class:day-selected={editing.weekdays.includes(d.n)} class="weekday" on:click={()=>toggleWeekday(d.n)}>{d.s}</button>{/each}</div></div>{/if}
    <div class="notes-field"><div class="flat-label">Notes</div><div class="word-editor"><div class="word-toolbar"><select class="font-select" aria-label="Font family" value={selectedFont} on:change={setEditorFont}><option value="">Font</option><option value="Arial">Arial</option><option value="Georgia">Georgia</option><option value="Times New Roman">Times New Roman</option><option value="Verdana">Verdana</option><option value="Courier New">Courier New</option><option value="Plus Jakarta Sans">Plus Jakarta Sans</option></select><select class="size-select" aria-label="Text size" value={selectedFontSize} on:change={setEditorFontSize}><option value="">Size</option>{#each [10,11,12,14,16,18,20,24,28,32,36] as size}<option value={String(size)}>{size}</option>{/each}</select><span class="toolbar-separator"></span><button type="button" class:format-active={editorIsBold} title="Bold" aria-label="Bold" on:mousedown|preventDefault on:click={()=>editorCommand('bold')}><Bold size={15}/></button><button type="button" class:format-active={editorIsItalic} title="Italic" aria-label="Italic" on:mousedown|preventDefault on:click={()=>editorCommand('italic')}><Italic size={15}/></button><button type="button" class:format-active={editorIsUnderline} title="Underline" aria-label="Underline" on:mousedown|preventDefault on:click={()=>editorCommand('underline')}><Underline size={15}/></button><button type="button" title="Strikethrough" aria-label="Strikethrough" on:mousedown|preventDefault on:click={()=>editorCommand('strike')}><Strikethrough size={15}/></button><span class="toolbar-separator"></span><select class="paragraph-select" aria-label="Paragraph style" value={selectedParagraphStyle} on:change={(event)=>setParagraphStyle(event.currentTarget.value)}><option value="p">Paragraph</option><option value="h2">Heading</option><option value="h3">Subheading</option></select><span class="toolbar-separator"></span><button type="button" title="Bulleted list" aria-label="Bulleted list" on:mousedown|preventDefault on:click={()=>editorCommand('bulletList')}><List size={15}/></button><button type="button" title="Numbered list" aria-label="Numbered list" on:mousedown|preventDefault on:click={()=>editorCommand('orderedList')}><ListOrdered size={15}/></button><span class="toolbar-separator"></span><button type="button" title="Upload image" aria-label="Upload image" on:mousedown|preventDefault on:click={insertImage}><ImagePlus size={15}/></button><input class="hidden" type="file" accept="image/*" bind:this={imageInput} on:change={loadNoteImage}/></div><div class="word-editor-content" bind:this={notesEditor}></div></div><small class="notes-hint">Images up to 5 MB · Paste or drop images here · Formatting is saved with this task</small></div>
  </div>
  {#if error}<p class="text-rose-600 text-xs mt-3">{error}</p>{/if}<div class="task-modal-footer"><button type="button" class="flat-btn flat-btn-ghost" on:click={closeTaskDialog}>Cancel</button><button class="task-save" type="submit"><Plus size={15}/> Save Task</button></div>
</form></div>{/if}
{#if resultDialog}<div class="modal-backdrop" role="presentation"><form class="modal-panel result-modal" on:submit|preventDefault={saveResult}>
  <div class="flex items-center justify-between mb-2"><h2 class="font-extrabold text-lg">Activity Result Form</h2><button type="button" class="p-1" aria-label="Close" on:click={closeResultDialog}><X size={18}/></button></div><p class="text-xs text-slate-500 mb-2">{activeTask?.title} · {selectedDate}</p><p class="text-xs text-slate-400 mb-5">Record completed work, outputs, and reflection for this task.</p>
  <div class="result-form-fields"><label class="flex items-center gap-2 text-xs font-semibold"><input type="checkbox" class="accent-[#5473E6]" bind:checked={result.done}/> Mark as completed</label>
    <div class="result-points"><div class="flat-label">What did you do?</div>{#each activityItems as item,i (i)}<div class="result-point-row"><span class="result-point-bullet">•</span><input class="flat-input result-point-input" bind:value={activityItems[i]} placeholder="Add a point..."/><button type="button" class="result-point-remove" aria-label="Remove point" on:click={()=>removeResultPoint('activity',i)}><X size={14}/></button></div>{/each}<button type="button" class="result-add-point" on:click={()=>addResultPoint('activity')}><Plus size={14}/> Add point</button></div>
    <div class="result-points"><div class="flat-label">Output / deliverable</div>{#each outputItems as item,i (i)}<div class="result-point-row"><span class="result-point-bullet">•</span><input class="flat-input result-point-input" bind:value={outputItems[i]} placeholder="Add a point..."/><button type="button" class="result-point-remove" aria-label="Remove point" on:click={()=>removeResultPoint('output',i)}><X size={14}/></button></div>{/each}<button type="button" class="result-add-point" on:click={()=>addResultPoint('output')}><Plus size={14}/> Add point</button></div>
    <div class="notes-field"><div class="flat-label">Summary / reflection</div><div class="word-editor"><div class="word-toolbar"><select class="font-select" aria-label="Font family" on:change={(event)=>setEditorFont(event,'summary')}><option value="">Font</option><option value="Arial">Arial</option><option value="Georgia">Georgia</option><option value="Times New Roman">Times New Roman</option><option value="Verdana">Verdana</option><option value="Courier New">Courier New</option><option value="Plus Jakarta Sans">Plus Jakarta Sans</option></select><select class="size-select" aria-label="Text size" on:change={(event)=>setEditorFontSize(event,'summary')}><option value="">Size</option>{#each [10,11,12,14,16,18,20,24,28,32,36] as size}<option value={String(size)}>{size}</option>{/each}</select><span class="toolbar-separator"></span><button type="button" title="Bold" aria-label="Bold" on:mousedown|preventDefault on:click={()=>editorCommand('bold','summary')}><Bold size={15}/></button><button type="button" title="Italic" aria-label="Italic" on:mousedown|preventDefault on:click={()=>editorCommand('italic','summary')}><Italic size={15}/></button><button type="button" title="Underline" aria-label="Underline" on:mousedown|preventDefault on:click={()=>editorCommand('underline','summary')}><Underline size={15}/></button><button type="button" title="Strikethrough" aria-label="Strikethrough" on:mousedown|preventDefault on:click={()=>editorCommand('strike','summary')}><Strikethrough size={15}/></button><span class="toolbar-separator"></span><select class="paragraph-select" aria-label="Paragraph style" on:change={(event)=>setParagraphStyle(event.currentTarget.value,'summary')}><option value="p">Paragraph</option><option value="h2">Heading</option><option value="h3">Subheading</option></select><span class="toolbar-separator"></span><button type="button" title="Bulleted list" aria-label="Bulleted list" on:mousedown|preventDefault on:click={()=>editorCommand('bulletList','summary')}><List size={15}/></button><button type="button" title="Numbered list" aria-label="Numbered list" on:mousedown|preventDefault on:click={()=>editorCommand('orderedList','summary')}><ListOrdered size={15}/></button><span class="toolbar-separator"></span><button type="button" title="Upload image" aria-label="Upload image" on:mousedown|preventDefault on:click={()=>summaryImageInput?.click()}><ImagePlus size={15}/></button><input class="hidden" type="file" accept="image/*" bind:this={summaryImageInput} on:change={loadSummaryImage}/></div><div class="word-editor-content summary-editor-content" bind:this={summaryEditorElement}></div></div><small class="notes-hint">You can format text or insert an image up to 5 MB.</small></div>
    <label class="flat-label">Actual duration (minutes)<input type="number" min="0" max="1440" class="flat-input" bind:value={result.actualMinutes}/></label>
  </div>
  {#if error}<p class="text-rose-600 text-xs mt-3">{error}</p>{/if}<div class="flex justify-end gap-2 mt-7"><button type="button" class="flat-btn flat-btn-ghost" on:click={closeResultDialog}>Cancel</button><button class="flat-btn flat-btn-primary" type="submit" disabled={!summaryEditorReady}>Save Result</button></div>
</form></div>{/if}

{#if confirmDialog}<div class="modal-backdrop action-backdrop" role="presentation"><dialog open class="modal-panel action-modal" aria-modal="true" aria-labelledby="action-confirm-title"><div class="action-modal-icon alert-icon" class:action-modal-danger={confirmDialog.danger}><img src={alertIcon} alt="" aria-hidden="true"/></div><h2 id="action-confirm-title">{confirmDialog.title}</h2><p>{confirmDialog.message}</p><div class="action-modal-buttons"><button class="flat-btn flat-btn-ghost" on:click={()=>confirmDialog=null}>Cancel</button><button class="flat-btn" class:action-confirm-danger={confirmDialog.danger} class:flat-btn-primary={!confirmDialog.danger} on:click={runConfirmedAction}>{confirmDialog.confirmLabel}</button></div></dialog></div>{/if}
{#if feedbackDialog}<div class="modal-backdrop action-backdrop" role="presentation"><dialog open class="modal-panel action-modal alert" class:feedback-success={feedbackDialog.success} class:success-animated={feedbackDialog.success} class:failed-animated={!feedbackDialog.success} aria-modal="true" aria-labelledby="action-feedback-title"><div class="action-modal-icon alert-icon" class:action-modal-success={feedbackDialog.success} class:action-modal-danger={!feedbackDialog.success}><img src={feedbackDialog.success?successAnimated:failedAnimated} alt={feedbackDialog.success?'Success':'Failed'} /></div><h2 id="action-feedback-title">{feedbackDialog.title}</h2>{#if !feedbackDialog.success}<p>{feedbackDialog.message}</p>{/if}<div class="action-modal-buttons"><button class="flat-btn flat-btn-primary" on:click={()=>feedbackDialog=null}>Got it</button></div></dialog></div>{/if}
{#if activityOverviewEntry}<div class="modal-backdrop action-backdrop" role="presentation"><dialog open class="modal-panel activity-overview-modal" aria-modal="true" aria-labelledby="completed-result-title"><div class="activity-overview-heading"><div><span class="activity-overview-icon"><BookOpen size={18}/></span><div><h2 id="completed-result-title">Activity Result Overview</h2><p>Completed task details</p></div></div><button class="task-close" aria-label="Close overview" on:click={closeActivityOverview}><X size={18}/></button></div><div class="activity-overview-task"><span class="category" style:background={palette[activityOverviewEntry.task.category]?.bg||'#f3f4f6'} style:color={palette[activityOverviewEntry.task.category]?.text||'#667085'}>{activityOverviewEntry.task.category}</span><div class="activity-overview-task-heading"><strong>{activityOverviewEntry.task.title}</strong>{#if aiScore!==null}<span class="achievement-score"><Trophy size={13}/> {activityOverviewEntry.result.date===today()?'TODAY':'SCORE'} · {aiScore}/100</span>{/if}</div><span>{activityOverviewEntry.result.date} · {activityOverviewEntry.task.start} · {activityOverviewEntry.task.duration} min planned</span></div>{#if activityOverviewEntry.result.activity}<section class="activity-overview-section"><h3>What did you do?</h3><p>{activityOverviewEntry.result.activity}</p></section>{/if}{#if activityOverviewEntry.result.output}<section class="activity-overview-section"><h3>Output / deliverable</h3><p>{activityOverviewEntry.result.output}</p></section>{/if}{#if activityOverviewEntry.result.summary}<section class="activity-overview-section"><h3>Summary / reflection</h3><p>{richTextPreview(activityOverviewEntry.result.summary)}</p></section>{/if}{#if !resultHasDetails(activityOverviewEntry.result)}<p class="activity-overview-empty">No activity details were recorded for this completed task.</p>{/if}{#if aiEvaluation}<section class="ai-evaluation-panel"><h3><Sparkles size={15}/> AI Evaluation</h3><div class="ai-evaluation-copy">{@html formatAIMarkdown(aiEvaluation)}</div></section>{/if}<div class="activity-overview-footer"><button class="activity-overview-evaluate" disabled={!defaultAIConnected()||aiEvaluating} on:click={evaluateActivity}><Sparkles size={15}/>{aiEvaluating?'Evaluating…':'AI Evaluate'}</button><span class="activity-overview-complete"><Check size={14}/> Completed</span>{#if activityOverviewEntry.result.actualMinutes}<span>{activityOverviewEntry.result.actualMinutes} min recorded</span>{/if}<button class="flat-btn flat-btn-primary activity-overview-done" on:click={closeActivityOverview}>Done</button></div></dialog></div>{/if}

